package com.jarvis.mobile.assistant;
import android.content.*; import android.graphics.Color; import android.service.voice.*; import android.view.*; import android.widget.*; import com.jarvis.mobile.brain.JarvisBrain;
public class JarvisVoiceSession extends VoiceInteractionSession { public JarvisVoiceSession(Context c){super(c);} public View onCreateContentView(){LinearLayout v=new LinearLayout(getContext());v.setOrientation(LinearLayout.VERTICAL);v.setPadding(30,30,30,30);v.setBackgroundColor(Color.argb(235,2,7,11));ImageView i=new ImageView(getContext());i.setImageResource(com.jarvis.mobile.R.drawable.ic_reactor);v.addView(i,new LinearLayout.LayoutParams(-1,220));TextView t=new TextView(getContext());t.setTextColor(Color.CYAN);t.setTextSize(20);t.setText("JARVIS\nAssistant session active");v.addView(t);Button b=new Button(getContext());b.setText("OPEN JARVIS");b.setOnClickListener(x->{Intent n=new Intent(getContext(),com.jarvis.mobile.MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);getContext().startActivity(n);});v.addView(b);return v;} }
